You are reviewing an offline harness that compares two model runner implementations. The module below is the whole implementation; review it as if it were about to land.

```python
from __future__ import annotations

import json
from dataclasses import dataclass
from pathlib import Path


@dataclass
class Diff:
    record_id: str
    greedy: bool
    exact: bool
    failures: list[str]


def load(path: str) -> list[dict]:
    text = Path(path).read_text(encoding="utf-8")
    return [json.loads(line) for line in text.splitlines() if line.strip()]


def first_divergence(a: list[str], b: list[str]) -> int:
    for position, (left, right) in enumerate(zip(a, b)):
        if left != right:
            return position
    return min(len(a), len(b))


def compare(a: list[dict], b: list[dict], max_delta: float = 0.05) -> list[Diff]:
    index_b = {record["id"]: record for record in b}
    diffs: list[Diff] = []
    for record in a:
        other = index_b[record["id"]]
        failures: list[str] = []
        exact = record["tokens"] == other["tokens"]
        if not exact and record["temperature"] == 0:
            failures.append(f"diverged at {first_divergence(record['tokens'], other['tokens'])}")
        deltas = [
            abs(left - right)
            for left, right in zip(record["logprobs"], other["logprobs"])
            if left is not None and right is not None
        ]
        if deltas and max(deltas) > max_delta:
            failures.append("logprob delta over threshold")
        diffs.append(Diff(record["id"], record["temperature"] == 0, exact, failures))
    return diffs


def summarize(diffs: list[Diff]) -> dict:
    total = len(diffs)
    exact = sum(1 for diff in diffs if diff.exact)
    return {
        "records": total,
        "exact_rate": exact / total if total else 0.0,
        "failing": [diff.record_id for diff in diffs if diff.failures],
    }


if __name__ == "__main__":
    import sys

    diffs = compare(load(sys.argv[1]), load(sys.argv[2]))
    print(json.dumps(summarize(diffs), indent=2))
```

